import fs from 'node:fs';import {poseTools,pack} from '../../review/command-pose.mjs';const root=new URL('../../',import.meta.url),bank=JSON.parse(fs.readFileSync(new URL('data/mix-bank.json',root))),t=poseTools(bank),source=JSON.parse(fs.readFileSync(new URL('data/external-neutral-turn-source.json',root)));const turns=[];
for(const c of source.clips){const frames=[],headings=[];for(let f=0;f<c.tracks[0].times.length;f++){const p=t.m.makePose();for(const tr of c.tracks){const i=t.m.index.get(tr.bone);if(i!==undefined)p[i].q.fromArray(tr.rotations.slice(f*4,f*4+4)).normalize();}t.m.fk(p);let a=-t.heading(p)*180/Math.PI;if(headings.length){while(a-headings.at(-1)>180)a-=360;while(a-headings.at(-1)<-180)a+=360;}headings.push(a);t.orient(p);frames.push(pack(p));}const angle=headings.at(-1)-headings[0];turns.push({id:c.id,name:'100STYLE Neutral · записанный поворот',duration:c.duration,frames,headingProgress:headings.map(a=>(a-headings[0])/angle),angle,coverage:c.tracks.map(tr=>tr.bone),provenance:c.provenance});}
fs.writeFileSync(new URL('data/external-neutral-turns.json',root),JSON.stringify({turns}));console.log(turns.map(c=>({id:c.id,angle:c.angle,frames:c.frames.length})));
